bool selfTest() {
  for (size_t i = 0; i < vectors::HMAC_COUNT; i++) {
    const auto& v = vectors::HMAC[i];
    char sig[crypto::SIG_HEX_LEN + 1];
    crypto::signEnvelope(v.secret, v.device_id, v.kind, v.ts, v.nonce, v.body, sig);
    if (!crypto::constTimeEqual(sig, v.sig)) {
      Serial.printf("HMAC SELFTEST FAILED on vector %u (%s): networking disabled\n", static_cast<unsigned>(i), v.kind);
      return false;
    }
  }
  Serial.printf("HMAC SELFTEST OK (%u vectors)\n", static_cast<unsigned>(vectors::HMAC_COUNT));
  return true;
}

// Signs body as `kind` (fresh ts + nonce every call, so a retry is never a replay) and publishes it.
// The envelope stays in `envelope` for `dump`.
bool sendSigned(const char* kind, const char* topic, const char* bodyStr) {
  char nonce[17];
  msg::nonceHex(esp_random(), esp_random(), nonce);
  lastKind = kind;
  lastSent = false;
  if (!msg::envelope(deviceId, secret, kind, net::nowUnix(), nonce, bodyStr, envelope, sizeof envelope)) {
    tooBig++;
    Serial.printf("[tx] %s envelope too large, dropped\n", kind);
    return false;
  }
  lastSent = net::publish(topic, envelope);
  if (lastSent) sent++;
  // Never log the secret; the first 4 signature chars are enough to match a message in the backend logs.
  const char* sig = strstr(envelope, "\"sig\":\"");
  Serial.printf("[tx] %-9s %4u B sig=%.4s... %s\n", kind, static_cast<unsigned>(strlen(envelope)), sig ? sig + 7 : "",
                lastSent ? "ok" : "FAILED");
  return lastSent;
}

// Live when the uplink is up and the publish succeeds; otherwise into the offline buffer with the same seq.
void deliverReading(Reading& r) {
  if (net::uplink()) {
    const LiveExtras live{static_cast<uint32_t>(buffer.size()), net::status().rssi, buffer.dropped()};
    if (msg::telemetryBody(r, &live, body, sizeof body) && sendSigned("telemetry", tTelemetry, body)) {
      recent.push(packReading(r));  // sent, not yet known to be stored: replayable (R1)
      return;
    }
  }
  buffer.push(packReading(r));
  buffered++;
}

void deliverEvent(uint32_t s, uint32_t ts, const char* type, const char* data_json) {
  const int code = eventCode(type);
  if (net::uplink() && msg::eventBody(s, ts, type, data_json, body, sizeof body) && sendSigned("event", tEvent, body)) {
    if (code >= 0) recent.push(packEvent(s, ts, code));  // replayable like a reading (data is not kept)
    return;
  }
  if (code < 0) return;
  buffer.push(packEvent(s, ts, code));  // buffered events keep type, seq and ts; data is not stored
  buffered++;
}

// Reading time needs a valid clock: before the first NTP sync there is no ts to give it, so it is dropped.
bool stamp(uint32_t& s, uint32_t& ts) {
  ts = net::nowUnix();
  if (!enabled || ts == 0) {
    noClock++;
    return false;
  }
  s = seq.next();
  return true;
}

void reply(const char* cmdId, bool ok, const char* detail) {
  if (msg::cmdackBody(cmdId, ok, detail, body, sizeof body)) sendSigned("cmdack", tCmdack, body);
}

// ROTATE_SECRET {nonce, ct, tag}: the new secret sealed under the current one (crypto::rotateOpen). On success it
// is stored in NVS first, then used for everything from here on, including this command's cmdack: the server
// accepts a message signed with its pending secret as the proof that the device switched, and promotes it.
void rotateSecret(const char* cmdId, JsonVariantConst args) {
  char next[crypto::SIG_HEX_LEN + 1];
  if (!crypto::rotateOpen(secret, args["nonce"] | "", args["ct"] | "", args["tag"] | "", next)) {
    rejected++;
    Serial.println("[cmd] ROTATE_SECRET refused: the sealed secret did not verify (key unchanged)");
    reply(cmdId, false, "sealed secret did not verify");
    return;
  }
  nvs::store().putStr(SECRET_KEY, next);  // persisted before use: a reboot right now still has the new key
  strcpy(rotatedSecret, next);
  secret = rotatedSecret;
  guard->setSecret(rotatedSecret);
  Serial.println("[cmd] ROTATE_SECRET ok: new device secret in use (config.h is now stale)");
  reply(cmdId, true, "secret rotated");
}

// Only authenticated commands get a cmdack: an attacker learns nothing from a rejected forgery.
void handleCommand(const net::Incoming& in) {
  JsonDocument cmd;
  const Verdict v = in.truncated ? Verdict::BAD_FIELDS : guard->verify(in.payload, "cmd", net::nowUnix(), cmd);
  const char* cmdId = cmd["cmd_id"];
  if (v != Verdict::OK || !cmdId) {
    rejected++;
    Serial.printf("[cmd] rejected: %s (total %lu)\n", v == Verdict::OK ? "BAD_FIELDS" : verdictName(v),
                  static_cast<unsigned long>(rejected));
    return;
  }
  const char* typeName = cmd["type"] | "";
  const CmdType type = parseCmdType(typeName);
  if (type == CmdType::UNKNOWN || !handler) {
    rejected++;
    Serial.printf("[cmd] rejected: type '%s' not allowed (total %lu)\n", typeName, static_cast<unsigned long>(rejected));
    reply(cmdId, false, "unknown command type");
    return;
  }
  if (type == CmdType::SYNC_REQUEST) {  // the server names the gap it found (R1); none: replay everything kept
    JsonVariantConst args = cmd["args"];
    replayRange = args["from_seq"].is<uint32_t>() && args["to_seq"].is<uint32_t>();
    replayFrom = replayRange ? args["from_seq"].as<uint32_t>() : 0;
    replayTo = replayRange ? args["to_seq"].as<uint32_t>() : 0;
  }
  if (type == CmdType::ROTATE_SECRET) {  // S7: the uplink owns the secret, so it handles this one itself
    rotateSecret(cmdId, cmd["args"]);
    return;
  }
  if (type == CmdType::SET_CALIBRATION) {  // P4: offset the DS18B20 reading; the server bounds it, we clamp too
    JsonVariantConst args = cmd["args"];
    if (args["offset_c"].isNull()) {
      reply(cmdId, false, "missing offset_c");
      return;
    }
    const float applied = sensors::setCalibration(args["offset_c"].as<float>());
    char d[48];
    snprintf(d, sizeof d, "offset %.2f C", applied);
    Serial.printf("[cmd] SET_CALIBRATION ok: %s\n", d);
    reply(cmdId, true, d);
    return;
  }
  char detail[64] = "";
  const bool ok = handler(type, detail, sizeof detail);
  Serial.printf("[cmd] %s %s: %s\n", typeName, ok ? "ok" : "failed", detail);
  reply(cmdId, ok, detail);
}

// Server ack {"seq_upto":N}, signed with the device secret and checked exactly like a command.
void handleAck(const net::Incoming& in) {
  JsonDocument ack;
  const Verdict v = in.truncated ? Verdict::BAD_FIELDS : guard->verify(in.payload, "ack", net::nowUnix(), ack);
  if (v != Verdict::OK || !ack["seq_upto"].is<uint32_t>()) {
    rejectedAcks++;
    Serial.printf("[ack] rejected: %s\n", v == Verdict::OK ? "BAD_FIELDS" : verdictName(v));
    return;
  }
  const uint32_t upto = ack["seq_upto"];
  const size_t before = buffer.size();
  if (syncer.onAck(upto)) {
    Serial.printf("[ack] seq_upto %lu: freed %u, %u left\n", static_cast<unsigned long>(upto),
                  static_cast<unsigned>(before - buffer.size()), static_cast<unsigned>(buffer.size()));
  }
}

void pumpSync(uint32_t now_ms) {
  if (!syncer.due(now_ms, net::uplink())) return;
  const size_t n = syncer.chunkSize();
  if (syncBody(buffer, n, body, sizeof body)) {
    sendSigned("sync", tSync, body);
    Serial.printf("[sync] seq %lu..%lu (%u readings), retry %lu\n", static_cast<unsigned long>(buffer.at(0).seq),
                  static_cast<unsigned long>(buffer.at(n - 1).seq), static_cast<unsigned>(n),
                  static_cast<unsigned long>(syncer.retries()));
  }
  syncer.sent(now_ms);  // even if the publish failed: the ack timeout drives the retry
}

